def longest_distinct_parity_balanced_subarray(nums):
    answer=0
    for left in range(len(nums)):
        seen=set();even=odd=0
        for right in range(left,len(nums)):
            value=nums[right]
            if value not in seen:
                seen.add(value)
                if value%2:odd+=1
                else:even+=1
            if even==odd:answer=max(answer,right-left+1)
    return answer

